import pathlib,json,hashlib,collections,numpy as np
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
src=R/'y06_r21_bear_combination_20261127.py'
P22=R/'Y06_R22_FROZEN_ROBUSTNESS_V2_PROTOCOL_20261127.json';O22=R/'Y06_R22_FROZEN_ROBUSTNESS_V2_RESULTS_20261127.json';assert not P22.exists() and not O22.exists()
p22={'status':'RESEARCH_ONLY_NO_LIVE','parent_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'frozen':'R21 room>=.5ATR AND (Binance 3h signed imbalance<0 OR BTC168h return>0), applied only to R18 bearish OLD24, NEW48 unchanged. R18 baseline comparator. No selection from grid; one-factor perturbations .25/.75/1 ATR, 120/216h low, sell imbalance -.02/+.02, BTC week +/-0.5%, plus base. Fees10/30/50/70bps. Same fixed tapes/portfolio; no genuinely untouched period.','funding':'ASTER archive TARGET only, exact actual rate timestamp, mark proxy M5 open, skip boundary events, audit file range and max gaps. Same entry acceptance as wallet absent nonpositive equity. Missing funding coverage means partial sensitivity, not full result.','controls':'128 calendar-month matched random thinning of bearish old candidates, same number, seed2026112722, no inferential independence. Leave-one-symbol-out frozen rule and concentration. No new thresholds selected.'}
P22.write_text(json.dumps(p22,indent=2),encoding='utf8')
s=src.read_text(encoding='utf8');start=s.index("s=parent.read_text()");end=s.index("oldflags=[")
