def feats(x,lowh):
 i=(x['entryTs']-bt.HS)//H;h=hs[x['symbol']];a=r3.calc_atr(h,i)
 room=None
 if i>=lowh+1 and a and np.isfinite(h[i-lowh-1:i-1,2]).all():room=float((h[i-1,3]-h[i-lowh-1:i-1,2].min())/a)
 w=btc[i-169:i,3]
 week=float(w[-1]/w[0]-1) if len(w)==169 and np.isfinite(w).all() else None
 return room,fl(binflow[x['symbol']],i),week
variants={'FROZEN':(.5,168,0,0),'ROOM025':(.25,168,0,0),'ROOM075':(.75,168,0,0),'ROOM100':(1,168,0,0),'LOW120':(.5,120,0,0),'LOW216':(.5,216,0,0),'SELL_M02':(.5,168,-.02,0),'SELL_P02':(.5,168,.02,0),'WEEK_M005':(.5,168,0,-.005),'WEEK_P005':(.5,168,0,.005)}
bf=[x for x in old if bear(x)];non=[x for x in old if not bear(x)]
tapes22={'R18':old+new};sel={}
for name,(r,l,f,w) in variants.items():
 a=[]
 for x in bf:
  room,flow,week=feats(x,l)
  if room is not None and room>=r and ((flow is not None and flow<f) or (week is not None and week>w)):a.append(x)
 sel[name]=a;tapes22[name]=a+non+new
out={}
for name,cs in tapes22.items():
 out[name]={}
 for per in bt.PERIODS:
  out[name][per]={str(f):wallet2([x for x in cs if x['period']==per],per,f,'FIFO') for f in (10,30,50,70)}
 print('BT',name,[(round(v['10']['terminal_jpy']),round(v['30']['terminal_jpy']),round(v['30']['max_dd_pct'],2),round(v['50']['terminal_jpy']),round(v['70']['terminal_jpy'])) for v in out[name].values()],flush=True)
# exact reproduction check
prev=json.loads((R/'Y06_R21_BEAR_COMBINATION_RESULTS_20261127.json').read_text())
for per in bt.PERIODS:
 assert abs(out['FROZEN'][per]['30']['terminal_jpy']-prev['results']['ROOM_SELL_OR_WEEKUP'][per]['30']['terminal_jpy'])<1e-6
print('REPRODUCTION_PASS',flush=True)
rng=np.random.default_rng(2026112722)
def mon(x):return datetime.datetime.fromtimestamp(x['entryTs']/1000,datetime.timezone.utc).strftime('%Y-%m')
controls={}
for per in bt.PERIODS:
 groups=collections.defaultdict(list);counts=collections.Counter(mon(x) for x in sel['FROZEN'] if x['period']==per)
 for x in bf:
  if x['period']==per:groups[mon(x)].append(x)
 fixed=[x for x in non+new if x['period']==per]
 vals=[]
 for _ in range(128):
  z=[groups[m][int(i)] for m,n in counts.items() for i in rng.choice(len(groups[m]),size=n,replace=False)]
  vals.append(wallet2(z+fixed,per,30,'FIFO')['terminal_jpy'])
 actual=out['FROZEN'][per]['30']['terminal_jpy'];controls[per]={'mean':float(np.mean(vals)),'p05':float(np.quantile(vals,.05)),'p95':float(np.quantile(vals,.95)),'beats':sum(actual>v for v in vals),'draws':vals}
 print('CONTROL',per,round(actual),round(np.mean(vals)),controls[per]['beats'],flush=True)
loo={}
for sym in bt.SYMS[1:]:
 loo[sym]={per:wallet2([x for x in tapes22['FROZEN'] if x['period']==per and x['symbol']!=sym],per,30,'FIFO') for per in bt.PERIODS}
 print('LOO',sym,[round(v['terminal_jpy']) for v in loo[sym].values()],flush=True)
# ASTER funding archive target: inspect actual file naming instead of assuming coverage.
fund={}
for sym in bt.SYMS[1:]:
 f=bt.ROOT/'aster-public-funding'/(sym+'USDT-20251001-20261001.json')
 if f.exists():
  a=sorted((int(x['fundingTime']),float(x['fundingRate'])) for x in json.loads(f.read_text(encoding='utf8')))
  fund[sym]=a
audit={s:{'n':len(a),'first':a[0][0] if a else None,'last':a[-1][0] if a else None,'max_gap_h':max(((b[0]-c[0])/H for c,b in zip(a,a[1:])),default=None)} for s,a in fund.items()}
def funded(cs,fee):
 begin,end=bt.PERIODS['TARGET'];eq=np.full((end-begin)//M+1,10000.);active=[];cool={};acc=[];cash=0.;events=0;missing=[];bounds=0
 for x in sorted(cs,key=lambda y:(y['entryTs'],y['symbol'],y['route'])):
  t=x['entryTs'];e=x['exitTs'];s=x['symbol'];active=[a for a in active if a['exitTs']>t]
  if not(begin<=t<e<end) or len(active)>=2 or any(a['symbol']==s for a in active) or t<cool.get(s,0):continue
  i=(t-begin)//M;j=(e-begin)//M;mi=(t-bt.MS)//M;nt=.30*eq[i];px=ms[s][mi:mi+j-i,0]
  if nt<=0 or len(px)!=j-i or not np.isfinite(px).all():continue
  a=fund.get(s,[]);prior=[v for v in a if v[0]<=t];after=[v for v in a if v[0]>=e];inside=[v for v in a if t<v[0]<e]
  valid=bool(prior and after) and max((v[0]-u[0] for u,v in zip([prior[-1]]+inside,inside+[after[0]])),default=0)<=8*H+M if prior and after else False
  ff=[]
  if valid:
   for ft,rate in inside:
    idx=(ft-begin+M-1)//M;k=(ft-bt.MS+M-1)//M
    if k>=len(ms[s]) or not np.isfinite(ms[s][k,0]):valid=False;break
    ff.append((idx,nt*float(ms[s][k,0])/x['entry']*rate))
  if not valid:missing.append((s,t));ff=[]
  bounds+=sum(ft in (t,e) for ft,rate in a)
  eq[i:j]+=nt*(1-px/x['entry']-fee/20000);net=nt*(x['rawReturn']-fee/10000);eq[j:]+=net
  for idx,v in ff:eq[idx:]+=v
  cash+=sum(v for idx,v in ff);events+=len(ff);acc.append(net+sum(v for idx,v in ff));active.append(x);cool[s]=e+12*H
 peak=np.maximum.accumulate(np.r_[10000.,eq])[1:]
 return {'terminal_jpy':float(eq[-1]),'max_dd_pct':float(100*np.max(1-eq/peak)),'n':len(acc),'wins':sum(v>0 for v in acc),'funding_jpy':float(cash),'funding_events':events,'missing_trades':missing,'boundary_excluded':bounds}
fresults={k:{str(f):funded([x for x in tapes22[k] if x['period']=='TARGET'],f) for f in (10,30)} for k in ('R18','FROZEN')}
print('FUNDING',json.dumps(fresults,default=lambda x:x.item()),flush=True)
O22.write_text(json.dumps({'protocol':p22,'protocol_sha256':hashlib.sha256(P22.read_bytes()).hexdigest(),'results':out,'controls':controls,'leave_one_symbol_out':loo,'funding_audit':audit,'funding_sensitivity':fresults},indent=2,allow_nan=False,default=lambda x:x.item()),encoding='utf8')
print('SAVED',hashlib.sha256(O22.read_bytes()).hexdigest(),flush=True)
